 private byte[] call(String... args)throws Exception {compatible();ArrayList<String> command=new ArrayList<>(Arrays.asList("/system/bin/service","call","onyx_device_service"));command.addAll(Arrays.asList(args));java.lang.Process p=new ProcessBuilder(command).redirectErrorStream(true).start();CompletableFuture<byte[]> output=CompletableFuture.supplyAsync(()->{try(InputStream in=p.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>1048576)throw new IOException("Native reply exceeds limit");out.write(b,0,n);}return out.toByteArray();}catch(IOException e){throw new CompletionException(e);}});if(!p.waitFor(10,TimeUnit.SECONDS)){p.destroyForcibly();throw new IOException("Native service timed out");}String raw=new String(output.get(2,TimeUnit.SECONDS),StandardCharsets.UTF_8);ByteArrayOutputStream decoded=new ByteArrayOutputStream();Matcher m=Pattern.compile("(?m)^\\s*0x[0-9a-fA-F]+:\\s*((?:[0-9a-fA-F]{8}(?:\\s+|$)){1,4})").matcher(raw);while(m.find())for(String w:m.group(1).trim().split("\\s+"))decoded.write(ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt((int)Long.parseLong(w,16)).array());if(decoded.size()==0){m=Pattern.compile("Parcel\\(\\s*((?:[0-9a-fA-F]{8}\\s+)+)").matcher(raw);if(m.find())for(String w:m.group(1).trim().split("\\s+"))decoded.write(ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt((int)Long.parseLong(w,16)).array());}byte[] reply=decoded.toByteArray();if(reply.length<8||ByteBuffer.wrap(reply).order(ByteOrder.LITTLE_ENDIAN).getInt()!=0)throw new IOException("Native configuration access denied");return reply;}
 JSONObject read(String key)throws Exception {if(!CLUSTER.equals(key)&&!SYSTEM.equals(key))throw new IOException("Unexpected configuration key");byte[] r=call("3","s16",key);int n=ByteBuffer.wrap(r).order(ByteOrder.LITTLE_ENDIAN).getInt(4);if(n<0||n>524288||8L+n*2L>r.length)throw new IOException("Malformed native configuration");return new JSONObject(new String(r,8,n*2,StandardCharsets.UTF_16LE));}
 static String canonical(Object v)throws JSONException {if(v instanceof JSONObject o){TreeMap<String,String> keys=new TreeMap<>();Iterator<String> i=o.keys();while(i.hasNext()){String k=i.next();keys.put(k,canonical(o.get(k)));}return keys.toString();}if(v instanceof JSONArray a){ArrayList<String> r=new ArrayList<>();for(int i=0;i<a.length();i++)r.add(canonical(a.get(i)));return r.toString();}return new JSONArray().put(v).toString();}
