 JSONObject flags()throws Exception {JSONObject c=read(SYSTEM).getJSONObject("configMap");return new JSONObject().put("notes",c.getString("key_enable_sync_note_data")).put("reader",c.getString("key_enable_sync_reader_data"));}
 void flags(JSONObject f)throws Exception {JSONObject c=read(SYSTEM);c.getJSONObject("configMap").put("key_enable_sync_note_data",f.getString("notes")).put("key_enable_sync_reader_data",f.getString("reader"));write(SYSTEM,c);context.sendBroadcast(new Intent("com.onyx.action.system.config.changed"));}
 JSONObject account()throws Exception {JSONObject r=new JSONObject().put("loggedIn",false);try(Cursor c=context.getContentResolver().query(ACCOUNTS,new String[]{"uid","clusterId"},"loggedIn=1",null,null)){if(c==null)throw new IOException("Native account provider unavailable");if(c.getCount()>1)throw new IOException("Multiple active native accounts");if(c.moveToFirst())r.put("loggedIn",true).put("uid",c.getString(0)).put("clusterId",c.getString(1));}return r;}
 String fingerprint()throws Exception {ArrayList<String> rows=new ArrayList<>();try(Cursor c=context.getContentResolver().query(Uri.parse("content://com.onyx.android.sdk.note.ContentProvider/NoteModel"),new String[]{"uniqueId","type","status","userId"},null,null,null)){if(c==null)throw new IOException("Native library unavailable");while(c.moveToNext())rows.add(c.getString(0)+":"+c.getInt(1)+":"+c.getInt(2)+":"+c.getString(3));}Collections.sort(rows);return hex(java.security.MessageDigest.getInstance("SHA-256").digest(String.join("\n",rows).getBytes(StandardCharsets.UTF_8)));}
