 private final class Binding implements AutoCloseable {final Handler main=new Handler(Looper.getMainLooper());final CompletableFuture<IBinder> future=new CompletableFuture<>();boolean bound;final ServiceConnection conn=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){future.complete(b);}public void onServiceDisconnected(ComponentName n){future.completeExceptionally(new IOException("Native service disconnected"));}public void onNullBinding(ComponentName n){future.completeExceptionally(new IOException("Native binding unavailable"));}};Binding(){main.post(()->{try{bound=context.bindService(new Intent().setComponent(new ComponentName("com.onyx.android.ksync","com.onyx.android.ksync.service.KSyncService")),conn,Context.BIND_AUTO_CREATE);if(!bound)future.completeExceptionally(new IOException("Native service denied binding"));}catch(Exception e){future.completeExceptionally(e);}});}IBinder get()throws Exception {IBinder b=future.get(15,TimeUnit.SECONDS);if(!SERVICE.equals(b.getInterfaceDescriptor()))throw new IOException("Unexpected native interface");return b;}public void close(){main.post(()->{if(bound){context.unbindService(conn);bound=false;}});}}
 void clusterCall(int transaction,String id)throws Exception {if(id!=null&&!id.matches("[a-zA-Z0-9_-]{1,80}"))throw new IOException("Invalid cluster identity");CompletableFuture<Integer> done=new CompletableFuture<>();Binder callback=new Binder(){protected boolean onTransact(int code,Parcel p,Parcel reply,int flags)throws RemoteException {if(code==INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.onyx.android.sdk.sync.ksync.service.SyncClusterCallback");return true;}if(code!=1)return super.onTransact(code,p,reply,flags);p.enforceInterface("com.onyx.android.sdk.sync.ksync.service.SyncClusterCallback");if(p.readInt()==0)done.completeExceptionally(new IOException("Empty native cluster callback"));else{p.readString();done.complete(p.readInt());}if(reply!=null)reply.writeNoException();return true;}};try(Binding b=new Binding()){Parcel p=Parcel.obtain();try{p.writeInterfaceToken(SERVICE);p.writeInt(1);p.writeString(id);p.writeInt(2);p.writeStrongBinder(callback);if(!b.get().transact(transaction,p,null,IBinder.FLAG_ONEWAY))throw new IOException("Cluster switch unsupported");}finally{p.recycle();}if(done.get(45,TimeUnit.SECONDS)!=2)throw new IOException("Native cluster switch failed");}}
 void updateClusters()throws Exception {clusterCall(81,null);}
 void switchCluster(String id)throws Exception {clusterCall(80,id);long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);while(!id.equals(read(CLUSTER).getString("curClusterId"))){if(System.nanoTime()>end)throw new IOException("Native selected cluster differs");Thread.sleep(300);}}
 void login(String account,String code,boolean master)throws Exception {CompletableFuture<Integer> done=new CompletableFuture<>();Binder cb=new Binder(){protected boolean onTransact(int c,Parcel p,Parcel reply,int f)throws RemoteException {if(c==INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.onyx.android.sdk.sync.ksync.service.AccountIntentCallback");return true;}if(c!=1)return super.onTransact(c,p,reply,f);p.enforceInterface("com.onyx.android.sdk.sync.ksync.service.AccountIntentCallback");if(p.readInt()==0)done.completeExceptionally(new IOException("Empty account callback"));else{p.readString();p.readString();p.readString();p.readInt();p.readString();p.readString();p.readString();p.readString();int status=p.readInt();p.readLong();p.readInt();p.readInt();p.readString();done.complete(status);}if(reply!=null)reply.writeNoException();return true;}};try(Binding b=new Binding()){Parcel p=Parcel.obtain();try{p.writeInterfaceToken(SERVICE);p.writeInt(1);p.writeString(master?null:account);p.writeString(master?null:code);p.writeString(null);p.writeInt(master?21:1);p.writeString(null);p.writeString("PowerSync");p.writeString(null);p.writeString(null);p.writeInt(0);p.writeLong(0);p.writeInt(master?0:2);p.writeInt(0);p.writeString(null);p.writeStrongBinder(cb);if(!b.get().transact(65,p,null,IBinder.FLAG_ONEWAY))throw new IOException("Native login unsupported");}finally{p.recycle();}int result=done.get(60,TimeUnit.SECONDS);if(result!=0)throw new IOException("Native sign-in failed (result "+result+")");}}
 JSONArray catalog()throws Exception {JSONArray a=new JSONArray();try(Cursor c=context.getContentResolver().query(Uri.parse("content://com.onyx.content.database.ContentProvider/Metadata"),null,null,null,null)){if(c==null)throw new IOException("Reader catalog unavailable");while(c.moveToNext()){if(a.length()>10000)throw new IOException("Reader catalog exceeds snapshot limit");JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++){Object v=switch(c.getType(i)){case Cursor.FIELD_TYPE_NULL -> JSONObject.NULL;case Cursor.FIELD_TYPE_INTEGER -> c.getLong(i);case Cursor.FIELD_TYPE_FLOAT -> c.getDouble(i);case Cursor.FIELD_TYPE_STRING -> c.getString(i);default -> throw new IOException("Unsupported catalog value");};row.put(c.getColumnName(i),v);}a.put(row);}}return a;}
 int repairMissingCatalog(JSONArray before)throws Exception {Uri uri=Uri.parse("content://com.onyx.content.database.ContentProvider/Metadata");int restored=0;for(int i=0;i<before.length();i++){JSONObject row=before.getJSONObject(i);String uuid=row.getString("uuid");try(Cursor c=context.getContentResolver().query(uri,new String[]{"uuid"},"uuid=?",new String[]{uuid},null)){if(c==null)throw new IOException("Reader catalog unavailable");if(c.moveToFirst())continue;}if(!new File(row.optString("nativeAbsolutePath")).isFile())throw new IOException("A pre-transition book is missing; preserve the baseline and inspect before continuing");try(Cursor c=context.getContentResolver().query(uri,new String[]{"id"},"id=?",new String[]{String.valueOf(row.get("id"))},null)){if(c==null||c.moveToFirst())throw new IOException("Original catalog ID unavailable for repair");}ContentValues values=new ContentValues();Iterator<String> keys=row.keys();while(keys.hasNext()){String k=keys.next();Object v=row.get(k);if(v==JSONObject.NULL)values.putNull(k);else if(v instanceof Integer||v instanceof Long)values.put(k,((Number)v).longValue());else if(v instanceof Number)values.put(k,((Number)v).doubleValue());else if(v instanceof String)values.put(k,(String)v);else throw new IOException("Unsupported catalog field");}if(context.getContentResolver().insert(uri,values)==null)throw new IOException("Reader catalog repair failed");JSONArray now=catalog();JSONObject found=null;for(int j=0;j<now.length();j++)if(uuid.equals(now.getJSONObject(j).optString("uuid")))found=now.getJSONObject(j);if(found==null||!canonical(row).equals(canonical(found)))throw new IOException("Restored catalog readback differs");restored++;}return restored;}
 boolean restoreAccount(JSONObject previous,String nativeUid)throws Exception {if(!previous.optBoolean("loggedIn"))return !account().optBoolean("loggedIn");String wanted=previous.getString("uid");if(wanted.equals(account().optString("uid")))return true;if(!"Go103_2Lumi".equals(Build.MODEL))return false;int matches=0,total=0;try(Cursor c=context.getContentResolver().query(ACCOUNTS,new String[]{"uid"},"(parent IS NULL OR parent='') AND uid<>?",new String[]{nativeUid},null)){if(c==null)return false;while(c.moveToNext()){total++;if(wanted.equals(c.getString(0)))matches++;}}if(total!=1||matches!=1)return false;context.getContentResolver().delete(ACCOUNTS,"uid=?",new String[]{nativeUid});login(null,null,true);return wanted.equals(account().optString("uid"));}

